SELECT CASE WHEN YEAR(start_date) < 2024 THEN 'before_2024' WHEN YEAR(start_date) = 2024 THEN '2024' ELSE 'after_2024' END AS start_cohort, SUM(monthly_fee) AS total_monthly_fee, COUNT(*) AS cnt, RANK() OVER (ORDER BY SUM(monthly_fee) DESC) AS rnk FROM subscriptions GROUP BY CASE WHEN YEAR(start_date) < 2024 THEN 'before_2024' WHEN YEAR(start_date) = 2024 THEN '2024' ELSE 'after_2024' END
